// C source
long total(long price, long qty, long tax) {
    return price * qty + tax;
}

; x86-64 assembly from gcc -O2 (Intel syntax). The arguments arrive
; in rdi, rsi and rdx, and the result is returned in rax.
total:
    imul  rdi, rsi           ; rdi = price * qty
    lea   rax, [rdi+rdx]     ; rax = rdi + tax
    ret                      ; jump back to the caller

; The same instructions as machine code bytes, in hex:
; 48 0f af fe     48 8d 04 17     c3

#define N 4096
int grid[N][N];          // row-major: grid[0][0..4095], then grid[1][...]

long fast(void) {        // walks memory in order (about 0.01 s on one test machine)
    long sum = 0;
    for (int row = 0; row < N; row++)
        for (int col = 0; col < N; col++)
            sum += grid[row][col];   // next element is 4 bytes away
    return sum;
}

long slow(void) {        // same additions, same machine: about 0.12 s
    long sum = 0;
    for (int col = 0; col < N; col++)
        for (int row = 0; row < N; row++)
            sum += grid[row][col];   // next element is a whole row (16 KB) away
    return sum;
}

